  [Token.TYPES.PARENTHESIS, Token.TYPES.FUNCTION].includes((lastOf(tokens) || {}).type)
);
const lastTokenIsExpression = (tokens, x) => x || lastTokenIsFunctionOrParenthesis(tokens);

/** @param {string} expr */
