    if (c === ' ') {
      if (i > 0) {
        const beforeWS = expr[i - 1],
          afterWS = expr.slice(i + 1);
        if (/\d/.test(beforeWS) && /^\s*\d/.test(afterWS)) {
          throw new Error('unexpected whitespace');
        }
      }
